// === LWB图片伪装（精简版 v2）===
// 职责只有一个：把 LWB 插画卡片「认领」成智绘姬(st-chatu8)能识别的图片。
//
// 约定（与目录里的 tauritavern改动.md 一致）：
// 1. 一次点击 = 一次幂等写入 + 一次消息编辑 + 一次宿主保存 + 一次刷新事件；
// 2. settings 里只写相对路径，绝不写 data: URL（内联图先落盘再写路径）；
// 3. 不覆盖已有条目，只追加（按 path 去重）；
// 4. 渲染完全交给智绘姬，失败就提示，不自绘假图（唯一例外：清理它自己也会清理的 chatu8Processed 标记）；
// 5. 找不到 [image: slot] 占位就拒绝操作，不猜位置；
// 6. 任何异常都冒到 toast，不留空 catch。
//
// 支持两种图：
// - 已保存：消息 extra.xiaobaixDrawSaved / LWB IndexedDB 的 savedUrl / /user/images 路径
// - 未保存：LWB IndexedDB 的 base64、或 DOM 里 blob:/data: 的即时预览 → 先上传成文件

$(errorCatched(() => {
    const TAG = 'LWB图片伪装';
    const LOG = `[${TAG}]`;
    const PARENT = window.parent || window;
    const DOC = PARENT.document;
    const DATA_URL = /^data:([^;]+);base64,/i;

    function fail(stage, error) {
        const message = error?.message || String(error);
        console.warn(LOG, stage, error);
        window.toastr?.error(message, `❌ ${TAG} · ${stage}`);
    }

    function sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    // ---------------------------------------------------------------- 样式
    function injectStyles() {
        const id = 'th-lwb-fake-style';
        let style = DOC.getElementById(id);
        if (!style) {
            style = DOC.createElement('style');
            style.id = id;
            DOC.head.appendChild(style);
        }
        style.textContent = `
            .th-lwb-fake-btn { position: absolute; top: 6px; left: 6px; z-index: 15; width: 22px; height: 22px;
                padding: 0; display: inline-flex; align-items: center; justify-content: center; cursor: pointer;
                background: rgba(0,0,0,.42); border: 1px solid rgba(255,255,255,.18); border-radius: 4px;
                color: rgba(255,255,255,.75); font-size: 11px; line-height: 1; opacity: .35;
                transition: opacity .2s, transform .2s, background .2s; user-select: none; }
            .xb-nd-img:hover .th-lwb-fake-btn { opacity: .75; }
            .th-lwb-fake-btn:hover { opacity: .98; background: rgba(16,185,129,.85); color: #fff; transform: scale(1.08); }
            .th-lwb-fake-btn.success { background: rgba(59,130,246,.75); color: #fff; opacity: .65; }
        `;
    }

    // ---------------------------------------------------------------- 上下文
    function getCtx() {
        const ctx = (PARENT.SillyTavern || window.SillyTavern)?.getContext?.();
        if (!ctx) throw new Error('无法获取 SillyTavern 上下文');
        return ctx;
    }

    // ---------------------------------------------------------------- LWB 预览记录
    // savedUrl = 已保存；base64 = 未保存（或尚未落盘）的即时预览
    function readPreview(imgId) {
        return new Promise(resolve => {
            let request;
            try {
                request = indexedDB.open('xb_novel_draw_previews');
            } catch (error) {
                console.warn(LOG, '打开 LWB 预览库失败', error);
                resolve(null);
                return;
            }
            request.onerror = () => resolve(null);
            request.onsuccess = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains('previews')) return resolve(null);
                const get = db.transaction('previews', 'readonly').objectStore('previews').get(imgId);
                get.onsuccess = () => resolve(get.result || null);
                get.onerror = () => resolve(null);
            };
        });
    }

    // ---------------------------------------------------------------- 内联图落盘
    function mimeToFormat(mime) {
        if (/jpe?g/i.test(mime)) return 'jpeg';
        if (/webp/i.test(mime)) return 'webp';
        return 'png';
    }

    function bytesToBase64(bytes) {
        let binary = '';
        const chunk = 0x8000;
        for (let i = 0; i < bytes.length; i += chunk) {
            binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
        }
        return btoa(binary);
    }

    // 未保存的图只有 data: / blob: 时，先上传成文件，settings 里永远只留相对路径。
    async function persistInline(ctx, source, imgId, mimeHint) {
        let base64;
        let mime = mimeHint || 'image/png';
        if (DATA_URL.test(source)) {
            mime = DATA_URL.exec(source)[1] || mime;
            base64 = source.slice(source.indexOf(',') + 1);
        } else if (/^blob:/i.test(source)) {
            const blob = await (await fetch(source)).blob();
            mime = blob.type || mime;
            base64 = bytesToBase64(new Uint8Array(await blob.arrayBuffer()));
        } else {
            base64 = source;
        }

        const format = mimeToFormat(mime);
        const extension = format === 'jpeg' ? 'jpg' : format;
        const fileName = `lwb_${imgId}.${extension}`;
        const reusable = `/user/images/${fileName}`;

        // 同一张图重复认领时复用已落盘的文件，避免反复上传
        const head = await fetch(reusable, { method: 'HEAD' }).catch(() => null);
        if (head?.ok) return reusable;

        const response = await fetch('/api/images/upload', {
            method: 'POST',
            headers: ctx.getRequestHeaders(),
            body: JSON.stringify({ image: base64, format, filename: fileName }),
        });
        if (!response.ok) throw new Error(`图片上传失败：${response.status} ${response.statusText}`);
        const result = await response.json();
        if (!result?.path) throw new Error('图片上传未返回路径');
        return result.path;
    }

    // ---------------------------------------------------------------- 找图：已保存 + 未保存
    async function resolveImagePath(card, ctx) {
        const imgId = (card.dataset.imgId || card.getAttribute('data-img-id') || '').trim();
        const slotId = (card.dataset.slotId || card.getAttribute('data-slot-id') || '').trim();
        const mesid = Number(card.dataset.mesid ?? card.closest?.('.mes')?.getAttribute('mesid') ?? -1);
        const message = mesid >= 0 ? ctx.chat?.[mesid] : null;

        // ① 消息 extra：已保存且可跨设备
        const savedMap = message?.extra?.xiaobaixDrawSaved || message?.extra?.novelDrawSaved;
        if (savedMap && slotId && savedMap[slotId]?.savedUrl) return savedMap[slotId].savedUrl;
        if (savedMap && imgId) {
            for (const key of Object.keys(savedMap)) {
                if (savedMap[key]?.imgId === imgId && savedMap[key]?.savedUrl) return savedMap[key].savedUrl;
            }
        }

        // ② LWB IndexedDB：已保存有 savedUrl；未保存只有 base64
        const preview = imgId ? await readPreview(imgId) : null;
        if (preview?.savedUrl) return preview.savedUrl;
        if (preview?.base64) return persistInline(ctx, preview.base64, imgId, preview.mime);

        // ③ DOM 当前渲染的图：/user/images 或 http 直接用；data:/blob: 说明还没落盘
        const img = card.querySelector('img');
        const src = img?.currentSrc || img?.src || '';
        if (src && (src.includes('/user/images/') || /^https?:/i.test(src))) return src;
        if (src && (/^data:/i.test(src) || /^blob:/i.test(src))) {
            return persistInline(ctx, src, imgId, img?.dataset?.mime);
        }

        throw new Error('找不到图片地址（未保存的图请先等 LWB 渲染出预览）');
    }

    // ---------------------------------------------------------------- 写入智绘姬配置
    function upsertClaim(ctx, md5, path) {
        const chatu8 = ctx.extensionSettings?.['st-chatu8'];
        if (!chatu8) throw new Error('未检测到智绘姬(st-chatu8)');
        chatu8.jiuguanStorage ??= {};
        const storage = chatu8.jiuguanStorage;

        const entry = storage[md5];
        if (entry && Array.isArray(entry.images) && entry.images.some(image => image.path === path)) {
            return 'already';
        }

        const image = {
            uuid: PARENT.crypto?.randomUUID?.() || String(Date.now()),
            path,
            date: Date.now(),
            isVideo: false,
            format: 'png',
            thumbnail_path: '', // 留空：智绘姬会回退用原图，避免把整张图再存一份
        };

        if (entry) {
            entry.images = Array.isArray(entry.images) ? entry.images : [];
            entry.images.push(image);
            if (typeof entry.index !== 'number') entry.index = 0;
        } else {
            storage[md5] = { images: [image], index: 0, change: '', video: '', activeMode: 'image' };
        }
        return 'added';
    }

    // ---------------------------------------------------------------- 消息文本
    function markerFor(imgId) {
        return `<image>image### ${imgId} ###</image>`;
    }

    // 先算出新的消息文本（找不到占位就直接抛），保证失败时 settings 一个字节都没动
    function planMarker(ctx, mesid, slotId, imgId) {
        const message = ctx.chat?.[mesid];
        if (!message || typeof message.mes !== 'string') throw new Error('消息不存在');
        if (message.mes.includes(`image### ${imgId} ###`)) return { changed: false, text: message.mes };

        if (!slotId) throw new Error('卡片缺少 data-slot-id，无法定位插入位置');
        const escaped = slotId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const slot = new RegExp(`(\\[(?:image|img|图片)\\s*:\\s*${escaped}[^\\]]*\\])`, 'i').exec(message.mes);
        if (!slot) throw new Error(`消息里找不到 [image: ${slotId}] 占位`);

        const at = slot.index + slot[0].length;
        return {
            changed: true,
            text: `${message.mes.slice(0, at)}\n\n${markerFor(imgId)}\n${message.mes.slice(at)}`,
        };
    }

    async function applyMarker(ctx, mesid, text) {
        const message = ctx.chat[mesid];
        message.mes = text;
        // 当前 swipe 同步：与宿主 saveChat 时的做法一致，否则重开聊天会被 swipes 覆盖
        if (Array.isArray(message.swipes) && typeof message.swipe_id === 'number') {
            message.swipes[message.swipe_id] = text;
        }
        await ctx.saveChat?.();
    }

    // ---------------------------------------------------------------- DOM 提示 + 等智绘姬接管
    // 只在卡片后面插一个纯文本标记，让智绘姬的 DOM 扫描能看到它；不自己画图。
    async function handoverToChatu8(card, imgId) {
        // 智绘姬用 dataset.chatu8Processed 记录"这条消息已处理过"，不清掉它就不会重新扫描新标记。
        // 这是本脚本唯一依赖智绘姬内部实现的地方，且只在该字段存在时清理。
        const mesText = card.closest?.('.mes')?.querySelector?.('.mes_text');
        if (mesText?.dataset) {
            delete mesText.dataset.chatu8Processed;
            delete mesText.dataset.chatu8ContentLength;
        }

        const holder = DOC.createElement('span');
        holder.className = 'lwb-fake-marker';
        holder.textContent = `\n${markerFor(imgId)}\n`;
        card.insertAdjacentElement('afterend', holder);

        const ctx = getCtx();
        ctx.eventSource?.emit('js_generation_ended');

        const deadline = Date.now() + 2000;
        while (Date.now() < deadline) {
            await sleep(120);
            const pending = holder.isConnected && holder.textContent.includes('image###');
            if (!pending) return true;
        }

        holder.remove();
        return false;
    }

    // ---------------------------------------------------------------- 主流程
    async function claim(card, button) {
        const ctx = getCtx();
        const imgId = (card.dataset.imgId || card.getAttribute('data-img-id') || '').trim();
        if (!imgId) throw new Error('卡片缺少 data-img-id');

        const slotId = (card.dataset.slotId || card.getAttribute('data-slot-id') || '').trim();
        const mesid = Number(card.dataset.mesid ?? card.closest?.('.mes')?.getAttribute('mesid') ?? -1);
        if (mesid < 0) throw new Error('无法确定消息楼层');

        const cryptoLib = PARENT.CryptoJS || window.CryptoJS;
        if (!cryptoLib?.MD5) throw new Error('未检测到 CryptoJS，无法计算图片 ID');

        const plan = planMarker(ctx, mesid, slotId, imgId); // 先校验，失败时什么都不写

        const path = await resolveImagePath(card, ctx);
        const md5 = cryptoLib.MD5(imgId).toString();

        const state = upsertClaim(ctx, md5, path);
        if (state === 'added') ctx.saveSettingsDebounced?.();

        if (plan.changed) await applyMarker(ctx, mesid, plan.text);

        const mounted = await handoverToChatu8(card, imgId);

        button.classList.add('success');
        button.innerHTML = '<span>✓</span>';
        if (state === 'already') {
            window.toastr?.info('这张图之前已经认领过，没有重复写入', `ℹ️ ${TAG}`);
        } else if (mounted) {
            window.toastr?.success('已认领并由智绘姬接管', `✨ ${TAG}`);
        } else {
            window.toastr?.info('已写入设置，但智绘姬没有即时接管；刷新或重新打开聊天后显示', `⚠️ ${TAG}`);
        }
    }

    // ---------------------------------------------------------------- 挂载
    // 不能用卡片上的 data 标记去重：LWB 重渲染时会调 pe() 同步属性
    // （dist/shared/draw-common-B7vWVSlh.js 里的 `for (const n of Object.keys(e.dataset)) if (!(n in t.dataset)) delete e.dataset[n]`），
    // 模板里没有的 data-* 会被删干净，`data-lwb-fake-mounted` 正好中招。
    // 而 `.xb-nd-img-wrap` 是原地更新的（只同步 img / nav-pill / status 三个子节点），
    // 旧按钮不会被清掉 → 标记没了就再挂一个 → 两个按钮叠在同一个位置。
    // 另一个坑：LWB 有时克隆节点再替换，克隆只复制 DOM、不复制事件监听，会留下点不动的死按钮。
    // 所以去重一律以 DOM 现状 + 活跃按钮集合为准，每次扫描收敛成「恰好一个可用的」。
    // 活跃集合挂在共享 window 上：万一脚本被导入两份（应用导入时会自己生成 id，与导出文件的 id 不同），
    // 两份实例必须认同「这是活按钮」，否则会互相删对方的按钮、每 200ms 抖一次。
    const LIVE = PARENT.__lwbFakeLiveButtons || (PARENT.__lwbFakeLiveButtons = new WeakSet());

    function createButton(card) {
        const button = DOC.createElement('button');
        button.type = 'button';
        button.className = 'th-lwb-fake-btn';
        button.title = '认领为智绘姬图片（启用原生修图/图生视频）';
        button.innerHTML = '<span>✨</span>';
        button.addEventListener('click', event => {
            event.stopPropagation();
            event.preventDefault();
            claim(card, button).catch(error => fail('认领失败', error));
        });
        LIVE.add(button);
        return button;
    }

    function mountButton(card) {
        if (!card) return;
        const wrap = card.querySelector('.xb-nd-img-wrap') || card;
        // 整卡范围内查，连挂到 card 上的漏网按钮一起收
        const existing = card.querySelectorAll('.th-lwb-fake-btn');
        if (existing.length === 1 && LIVE.has(existing[0])) return;
        existing.forEach(button => button.remove());
        wrap.appendChild(createButton(card));
    }

    function scan() {
        DOC.querySelectorAll('.xb-nd-img').forEach(mountButton);
    }

    let scanTimer = null;
    function scheduleScan() {
        if (scanTimer) return;
        scanTimer = setTimeout(() => {
            scanTimer = null;
            scan();
        }, 200);
    }

    injectStyles();
    scan();

    const chatRoot = DOC.querySelector('#chat') || DOC.body;
    if (chatRoot) {
        new MutationObserver(scheduleScan).observe(chatRoot, { childList: true, subtree: true });
    }

    console.log(LOG, '已就绪（精简版 v2）');
}));
